// ============================================================
// URL ROUTING — Sync URL avec state pour partage et tracking
// ============================================================

const slugify = (str) => {
  if (!str) return "";
  return String(str)
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");
};

const PAGE_TO_PATH = {
  home: "/",
  library: "/ma-bibliotheque",
  catalog: "/catalogue",
  carrycare: "/carrycare",
  quiz: "/carry-quiz",
  detail: "/livre",
  reader: "/lecture",
  myResults: "/mes-resultats",
  myResultDetail: "/mes-resultats",
  about: "/a-propos",
  faq: "/faq",
  favorites: "/favoris",
  referral: "/parrainage",
  confidentialite: "/confidentialite",
};

const PATH_TO_PAGE = {
  "/": "home",
  "/ma-bibliotheque": "library",
  "/catalogue": "catalog",
  "/carrycare": "carrycare",
  "/carry-quiz": "quiz",
  "/mes-resultats": "myResults",
  "/a-propos": "about",
  "/faq": "faq",
  "/favoris": "favorites",
  "/parrainage": "referral",
  "/confidentialite": "confidentialite",
};

const getPageFromURL = () => {
  const path = window.location.pathname;
  if (path.startsWith("/livre/")) return "detail";
  if (path.startsWith("/lecture/")) return "reader";
  if (path.startsWith("/mes-resultats/") && path.length > 16) return "myResultDetail";

  // 🎯 URLs de diagnostic CarryCare (pour pubs Facebook)
  const diagnosticUrls = [
    "/diagnostic-facial", "/diagnostic-visage",
    "/diagnostic-corporel", "/diagnostic-corps",
    "/diagnostic-capillaire", "/diagnostic-cheveux",
    "/garde-la-ligne", "/diagnostic-ligne"
  ];
  if (diagnosticUrls.includes(path.toLowerCase())) return "carrycare";

  return PATH_TO_PAGE[path] || "home";
};

const getSlugFromURL = () => {
  const path = window.location.pathname;
  if (path.startsWith("/livre/")) return path.replace("/livre/", "");
  if (path.startsWith("/lecture/")) return path.replace("/lecture/", "");
  return null;
};

const buildPath = (page, book) => {
  // 🎯 PRÉSERVER les URLs de diagnostic CarryCare (pour pubs Facebook)
  if (page === "carrycare" && typeof window !== "undefined") {
    const currentPath = window.location.pathname.toLowerCase();
    const diagnosticUrls = [
      "/diagnostic-facial", "/diagnostic-visage",
      "/diagnostic-corporel", "/diagnostic-corps",
      "/diagnostic-capillaire", "/diagnostic-cheveux",
      "/garde-la-ligne", "/diagnostic-ligne"
    ];
    if (diagnosticUrls.includes(currentPath)) {
      return currentPath;
    }
  }

  const base = PAGE_TO_PATH[page] || "/";
  if ((page === "detail" || page === "reader") && book) {
    return `${base}/${slugify(book.title || book.id)}`;
  }
  return base;
};

