// HELPER : Génère l'analyse "Ce qui se passe sur tes cheveux"
function generateCapAnalysis(texture, etat, problems, lifestyle) {
  let parts = [];
  
  // Analyse selon texture
  if (texture === "4A" || texture === "4B" || texture === "4C") {
    parts.push("Tes cheveux crépus ont une structure naturellement plus sèche : les huiles sécrétées par ton cuir chevelu ont du mal à descendre tout le long de la fibre à cause des nombreuses spirales. C'est pour ça qu'ils ont besoin d'hydratation EXTERNE plus que les autres types.");
  } else if (texture === "3A" || texture === "3B" || texture === "3C") {
    parts.push("Tes cheveux bouclés sont entre les deux mondes : ils peuvent être à la fois secs aux pointes et gras à la racine. Le défi est de bien hydrater sans alourdir.");
  } else if (texture === "ne_sait_pas") {
    parts.push("Pas de souci si tu ne connais pas ton type exact ! Les conseils ci-dessous fonctionnent pour la majorité des cheveux africains et métissés.");
  }

  // Analyse selon état
  if (etat === "defrise") {
    parts.push("Tes cheveux défrisés ont subi un traitement chimique qui a modifié leur structure. Ils sont plus fragiles et nécessitent des soins protéinés réguliers pour ne pas casser.");
  } else if (etat === "transition") {
    parts.push("Tu es en transition : tu as 2 textures différentes sur la même tête (racines naturelles + longueurs défrisées). C'est la zone de jonction (line of demarcation) qui est la plus fragile - sois douce avec elle !");
  } else if (etat === "tresses" || etat === "perruques") {
    parts.push("Le port fréquent de tresses ou perruques peut être bénéfique (protection) MAIS attention à ne pas serrer aux racines (alopécie de traction). Hydrate tes cheveux sous les tresses régulièrement.");
  } else if (etat === "colore") {
    parts.push("La coloration ouvre tes écailles capillaires. Tes cheveux ont besoin de soins protéinés pour reformer leur structure, et de masques nourrissants réguliers.");
  }

  // Problèmes principaux
  if (problems.includes("chute") || problems.includes("alopecie_traction")) {
    parts.push("⚠️ La chute de cheveux peut avoir plusieurs causes : tresses trop serrées, carence en fer/protéines, stress, post-partum, problème thyroïde. Si la chute est massive et persistante, consulte un dermatologue.");
  }
  if (problems.includes("pellicules")) {
    parts.push("Les pellicules sont causées par un champignon (Malassezia) qui se nourrit de l'huile du cuir chevelu. Le traitement = shampoing antifongique 2x/sem + arrêt des produits gras sur le cuir chevelu.");
  }
  if (problems.includes("secs")) {
    parts.push("La sécheresse vient souvent d'un manque d'hydratation INTERNE (eau bue) + manque de scellage avec une huile/beurre après l'eau. La règle d'or : eau D'ABORD, huile/beurre EN DERNIER.");
  }
  if (problems.includes("lents")) {
    parts.push("Les cheveux poussent en moyenne 1-1,5 cm/mois. Si les tiens semblent ne pas pousser, ce n'est pas que la pousse a stoppé - c'est que les pointes cassent au même rythme. Solution : protéger les pointes, couper les fourchues, masser le cuir chevelu.");
  }

  return parts;
}

// HELPER : Routine matin selon profil
function getCapMorningRoutine(texture, etat, problems, objectives) {
  const isFra = texture === "4A" || texture === "4B" || texture === "4C" || etat === "defrise";
  const steps = [];
  
  steps.push({ titre: "Hydratation", desc: "Vaporise un mélange eau + leave-in sur tes cheveux pour les réveiller et redéfinir." });
  
  if (isFra) {
    steps.push({ titre: "Sceller avec une huile/beurre", desc: "Applique une petite quantité d'huile (jojoba, ricin) ou de beurre de karité pour sceller l'hydratation." });
  }
  
  if (problems.includes("frisottis") || problems.includes("no_definition")) {
    steps.push({ titre: "Définition (optionnel)", desc: "Si tu veux définir tes boucles, applique un gel coiffant en méthode prière (smoothing)." });
  }
  
  steps.push({ titre: "Protéger en journée", desc: "Si tu portes un foulard ou bonnet en satin/soie, ça protège tes cheveux du frottement." });
  
  return steps;
}

// HELPER : Routine soir selon profil  
function getCapEveningRoutine(texture, etat, problems) {
  const steps = [];
  steps.push({ titre: "Démêler en douceur", desc: "Utilise un peigne large ou tes doigts pour démêler des pointes vers les racines (jamais l'inverse)." });
  steps.push({ titre: "Hydrater si besoin", desc: "Si tes cheveux sont très secs, refais une mini hydratation (vapo eau + leave-in)." });
  steps.push({ titre: "Tresser ou rouler", desc: "Fais des grosses tresses ou un chignon ample pour la nuit." });
  steps.push({ titre: "Bonnet ou taie en satin/soie", desc: "ESSENTIEL : ça évite le frottement contre l'oreiller, qui assèche et casse les cheveux. Investis dans une taie en satin." });
  return steps;
}

