// Helper pour détecter les WebViews Facebook/Instagram/TikTok
// (où Google OAuth ne fonctionne pas)
function isInAppBrowser() {
  if (typeof window === "undefined") return false;
  const ua = navigator.userAgent || navigator.vendor || window.opera || "";
  // Facebook : FB_IAB, FBAV, FBAN
  // Instagram : Instagram
  // TikTok : musical_ly, BytedanceWebview
  // Snapchat : Snapchat
  // LinkedIn : LinkedInApp
  return /FBAN|FBAV|FB_IAB|Instagram|musical_ly|BytedanceWebview|Snapchat|LinkedInApp/i.test(ua);
}

// Helper pour calculer le pourcentage de promo
function getDiscountPct(book) {
  if (!book) return 0;
  if (!book.original_price || !book.price) return 0;
  if (book.original_price <= book.price) return 0;
  return Math.round((1 - book.price / book.original_price) * 100);
}

function isOnPromo(book) {
  return getDiscountPct(book) > 0;
}

// Helper pour détecter un livre "papier uniquement"
// Critère : has_paper_version = true ET (prix numérique = 0 ou vide) ET pas de PDF valide
function isPaperOnly(book) {
  if (!book) return false;
  if (!book.has_paper_version) return false;
  // Si le livre a un prix numérique > 0, ce n'est pas "papier uniquement" (c'est mixte)
  if (book.price && book.price > 0) return false;
  // Si le livre a un PDF valide (pas "pending" ni vide), ce n'est pas "papier uniquement"
  const hasPdf = book.pdf_url && typeof book.pdf_url === 'string' && book.pdf_url.trim() !== "" && book.pdf_url !== "pending";
  if (hasPdf) return false;
  // Sinon c'est un livre papier uniquement
  return true;
}

// Helper pour générer un code parrainage suggéré (style PRENOM + 4 caractères)
function generateSuggestedReferralCode(name) {
  const cleanName = (name || "USER").replace(/[^a-zA-Z]/g, "").toUpperCase().slice(0, 8);
  const random = Math.random().toString(36).substring(2, 6).toUpperCase();
  return cleanName + random;
}

// Helper pour tracker les événements Meta Pixel (Facebook)
// Vérifie que fbq existe (le Pixel peut être bloqué par AdBlock ou indisponible)
function trackPixelEvent(eventName, params = {}) {
  try {
    if (typeof window !== "undefined" && typeof window.fbq === "function") {
      if (Object.keys(params).length > 0) {
        window.fbq("track", eventName, params);
      } else {
        window.fbq("track", eventName);
      }
    }
  } catch (e) {
    // Silent fail si Pixel pas disponible
  }
}

// 🔥 Helper pour envoyer les conversions à l'API Meta côté serveur (Supabase)
// Capte 100% des conversions, même celles bloquées par AdBlock/iOS/data savers
// Fonctionne en parallèle du Pixel JS - Meta dédoublonne automatiquement
async function trackMetaConversion(data) {
  try {
    await fetch("https://huikxujxsklboejkbnda.supabase.co/functions/v1/meta-conversion", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        status: "SUCCESSFUL",
        reference: data.reference || ("conv_" + Date.now()),
        amount: String(data.amount || 0),
        currency: "XAF",
        description: data.description || "",
        external_reference: data.external_reference || "",
        external_user: data.email || "",
        phone_number: data.phone || ""
      })
    });
  } catch (e) {
    // Silent fail - on ne bloque jamais l'utilisateur si Meta API échoue
    console.error("Meta API conversion error:", e);
  }
}

// 🛡️ Helper : Enregistre l'INTENTION d'achat AVANT confirmation CamPay
// Si la connexion coupe pendant le paiement, on pourra retrouver l'achat plus tard
async function recordPendingPurchase(data) {
  try {
    await fetch("/api/campay", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        action: "record_pending",
        reference: data.reference,
        user_id: data.user_id,
        type: data.type, // 'book', 'subscription', 'quiz'
        book_id: data.book_id || null,
        amount: data.amount,
        phone: data.phone || null,
        metadata: data.metadata || null
      })
    });
  } catch (e) {
    // Silent fail - ne JAMAIS bloquer le paiement même si l'enregistrement échoue
    console.error("recordPendingPurchase error:", e);
  }
}

// 🛡️ Helper : Récupère les achats perdus d'un user (paiements réussis mais non livrés)
// Appelé au chargement de la bibliothèque
async function recoverLostPurchases(user_id) {
  try {
    const res = await fetch("/api/campay", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        action: "recover_lost_purchases",
        user_id: user_id
      })
    });
    const data = await res.json();
    return data.recovered || [];
  } catch (e) {
    console.error("recoverLostPurchases error:", e);
    return [];
  }
}

